import{_ as d,o as e,c as o,a3 as a}from"./chunks/framework.BLaSdaBb.js";const m=JSON.parse('{"title":"NACT Framing","description":"","frontmatter":{},"headers":[],"relativePath":"transport/nact/framing.md","filePath":"transport/nact/framing.md","lastUpdated":1788343005000}'),r={name:"transport/nact/framing.md"};function c(s,t,h,n,i,l){return e(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="nact-framing" tabindex="-1">NACT Framing <a class="header-anchor" href="#nact-framing" aria-label="Permalink to &quot;NACT Framing&quot;">​</a></h1><p>无论是否分片，NACT 都会为每段字节增加 32 Bytes Header。</p><h2 id="nact-消息头" tabindex="-1">NACT 消息头 <a class="header-anchor" href="#nact-消息头" aria-label="Permalink to &quot;NACT 消息头&quot;">​</a></h2><div style="overflow-x:auto;"><table style="display:table;overflow:visible;min-width:960px;table-layout:fixed;text-align:center;"><thead><tr><th style="width:72px;">Offset</th><th>+0</th><th>+1</th><th>+2</th><th>+3</th><th>+4</th><th>+5</th><th>+6</th><th>+7</th><th>+8</th><th>+9</th><th>+A</th><th>+B</th><th>+C</th><th>+D</th><th>+E</th><th>+F</th></tr></thead><tbody><tr><th><code>0x00</code></th><td colspan="16"><code>msgId</code><br>16 B</td></tr><tr><th><code>0x10</code></th><td colspan="4"><code>offset</code><br>4 B</td><td colspan="4"><code>totalSize</code><br>4 B</td><td colspan="4"><code>thisFrameSize</code><br>4 B</td><td colspan="2"><code>blank</code><br>2 B</td><td><code>magic</code><br>1 B</td><td><code>version</code><br>1 B</td></tr></tbody></table></div><p>Frame Body 紧跟在 32B Header 后，从 <code>0x20</code> 开始，长度为 <code>thisFrameSize - 32</code>。</p><table tabindex="0"><thead><tr><th>Offset</th><th>长度</th><th>字段</th><th>编码</th><th>v1 值</th><th>含义</th></tr></thead><tbody><tr><td>0</td><td>16</td><td><code>msgId</code></td><td>16 bytes</td><td>-</td><td>同一<strong>NACP</strong>消息所有片相同</td></tr><tr><td>16</td><td>4</td><td><code>offset</code></td><td>uint32, BE</td><td>—</td><td>本片在整条消息中的起始字节</td></tr><tr><td>20</td><td>4</td><td><code>totalSize</code></td><td>uint32, BE</td><td>—</td><td>整条消息长度</td></tr><tr><td>24</td><td>4</td><td><code>thisFrameSize</code></td><td>uint32, BE</td><td>—</td><td><strong>本片总长，含这 32B 头</strong>，故 <code>bodyLen = thisFrameSize - 32</code>。</td></tr><tr><td>28</td><td>2</td><td><code>blank</code></td><td>uint16, BE</td><td><code>0x0000</code></td><td>预留给未来的指示位</td></tr><tr><td>30</td><td>1</td><td><code>magic</code></td><td>uint8</td><td><code>0xCF</code></td><td>魔数</td></tr><tr><td>31</td><td>1</td><td><code>version</code></td><td>uint8</td><td><code>0x01</code></td><td>NACT Message版本</td></tr></tbody></table><p>错误的版本会出现 <code>version-mismatch</code> 错误，版本正确但 magic 不匹配会出现 <code>bad-magic</code> 错误。</p><p>出错后都强制断连，没有向未来兼容解析。</p><div class="danger custom-block"><p class="custom-block-title">DANGER</p><p>由于totalSize只包含4Bytes，因此最大的长度只有2^(4*8)-1 Bytes，即约4GB。换句话说NACT理论上最大能承载一个4GB的消息发送。</p><p>这个数字其实是原先Node20对Buffer的最大限制，尽管在Node24中上限被提高到了8PB。</p><p>不过，实际传输中这个限制被NACP进一步调低，默认是2GB。</p><p><strong>（NASDK v1.0.3，NACT v1）</strong> 未来可能会通过增加头部长度、缩短msgID或利用Blank字段提升长度限制。<s>但是至少最近一段时间不会考虑修改NACT</s></p></div><h2 id="分片与重组" tabindex="-1">分片与重组 <a class="header-anchor" href="#分片与重组" aria-label="Permalink to &quot;分片与重组&quot;">​</a></h2><p>NACT 内有分片机制，对于一个较大的Payload消息，NACT会切分为多个帧按序发送。</p><p>tcp / ws 承载链路默认按照 100MB 分片，同机 unix 默认不分片。</p><p>NACT 分片是设计是为穿透 TCP / WebSocket 的中间层（如 CDN 的单帧上限），同时进一步降低了内存占用。</p><details class="details custom-block"><summary>Details</summary><p>1GB payload 实测：</p><table tabindex="0"><thead><tr><th>承载</th><th>分片</th><th>wire (ms)</th><th>接收端内存峰值</th></tr></thead><tbody><tr><td>unix</td><td>不分片</td><td>665</td><td>1024 MB</td></tr><tr><td>unix</td><td>100MB × 11</td><td>668</td><td>1024 MB</td></tr><tr><td>tcp</td><td>不分片</td><td>734</td><td>1024 MB</td></tr><tr><td>tcp</td><td>100MB × 11</td><td>667</td><td>1024 MB</td></tr><tr><td>ws</td><td>不分片</td><td>2784</td><td>3027 MB</td></tr><tr><td>ws</td><td>100MB × 11</td><td>3931</td><td><strong>1147 MB</strong></td></tr></tbody></table><p>Q：这里为什么会x11</p><p>A：因为NACT保证的是<strong>添加头之后产出的包最大是100MB</strong>，所以每次只会截取<code>100MB-32B</code>的数据，最后还有<code>32B+320B</code>数据需要单独发送。</p></details>',14)])])}const B=d(r,[["render",c]]);export{m as __pageData,B as default};
